class Solution {
    public String reverseWords(String s) {
        String[] words = s.trim().split("\\s+");
        if (words.length == 1 && words[0].isEmpty()) return "";
        StringBuilder sb = new StringBuilder();
        for (int i = words.length - 1; i >= 0; i--) {
            sb.append(words[i]);
            if (i > 0) sb.append(" ");
        }
        return sb.toString();
    }
}

