    string reverseWords(string s) {
        reverse(s.begin(), s.end());
        int n = s.size();
        int i = 0;
        while (i < n) {
            while (i < n && s[i] == ' ') i++;
            if (i >= n) break;
            int j = i;
            while (j < n && s[j] != ' ') j++;
            reverse(s.begin() + i, s.begin() + j);
            i = j;
        }
        return cleanSpaces(s);
    }
private:
    string cleanSpaces(string &s) {
        int n = s.size();
        int i = 0, j = 0;
        while (j < n) {
            while (j < n && s[j] == ' ') j++;
            while (j < n && s[j] != ' ') s[i++] = s[j++];
            while (j < n && s[j] == ' ') j++;
            if (j < n) s[i++] = ' ';
        }
        s.resize(i);
        return s;
    }
};

