class Solution:
    def reverseWords(self, s: str) -> str:
        a = list(s)
        self.reverse(a, 0, len(a) - 1)
        self.reverse_each_word(a)
        return self.clean_spaces(a)
    def reverse(self, a, l, r):
        while l < r:
            a[l], a[r] = a[r], a[l]
            l += 1
            r -= 1
    def reverse_each_word(self, a):
        n = len(a)
        i = 0
        while i < n:
            while i < n and a[i] == ' ':
                i += 1
            if i >= n:
                break
            j = i
            while j < n and a[j] != ' ':
                j += 1
            self.reverse(a, i, j - 1)
            i = j
    def clean_spaces(self, a):
        n = len(a)
        i = 0
        j = 0
        while j < n:
            while j < n and a[j] == ' ':
                j += 1
            while j < n and a[j] != ' ':
                a[i] = a[j]
                i += 1
                j += 1
            while j < n and a[j] == ' ':
                j += 1
            if j < n:
                a[i] = ' '
                i += 1
        return ''.join(a[:i])

