class Solution {
    public String reverseWords(String s) {
        char[] a = s.toCharArray();
        reverse(a, 0, a.length - 1);
        reverseEachWord(a);
        return cleanSpaces(a);
    }
    private void reverse(char[] a, int l, int r) {
        while (l < r) {
            char t = a[l];
            a[l++] = a[r];
            a[r--] = t;
        }
    }
    private void reverseEachWord(char[] a) {
        int n = a.length;
        int i = 0;
        while (i < n) {
            while (i < n && a[i] == ' ') i++;
            if (i >= n) break;
            int j = i;
            while (j < n && a[j] != ' ') j++;
            reverse(a, i, j - 1);
            i = j;
        }
    }
    private String cleanSpaces(char[] a) {
        int n = a.length;
        int i = 0, j = 0;
        while (j < n) {
            while (j < n && a[j] == ' ') j++;
            while (j < n && a[j] != ' ') a[i++] = a[j++];
            while (j < n && a[j] == ' ') j++;
            if (j < n) a[i++] = ' ';
        }
        return new String(a, 0, i);
    }
}
